[{"order":1,"type":"heading","text":"Reflection and Runtime Type Inspection in Go (Golang)"},{"order":2,"type":"paragraph","text":"Go is a statically typed language, but it provides a powerful package called 'reflect' that allows programs to examine their own structure at runtime. Reflection is commonly used when dealing with values of unknown types, writing generic serialization libraries (like JSON encoders), or inspecting struct tags."},{"order":3,"type":"subheading","text":"Understanding Type and Value"},{"order":4,"type":"paragraph","text":"At the core of Go reflection are two primary concepts represented by the 'reflect' package: 'reflect.Type' and 'reflect.Value'. A 'reflect.Type' represents the Go type of a variable, while a 'reflect.Value' holds the actual data value."},{"order":5,"type":"code","text":"package main

import (
	"fmt"
	"reflect"
)

func main() {
	var x float64 = 3.4
	v := reflect.ValueOf(x)
	t := reflect.TypeOf(x)

	fmt.Println("Type:", t)
	fmt.Println("Value:", v)
	fmt.Println("Kind:", v.Kind())
	fmt.Println("Type as Float64:", v.Float())
}"},{"order":6,"type":"subheading","text":"Modifying Values with Reflection"},{"order":7,"type":"paragraph","text":"By default, reflection works on copies of values. If you want to modify a variable through reflection, you must pass a pointer to the variable. You then call 'Elem()' on the reflection value to get the underlying variable it points to."},{"order":8,"type":"code","text":"package main

import (
	"fmt"
	"reflect"
)

func main() {
	var x float64 = 3.4
	p := reflect.ValueOf(&x) // Note the pointer
	v := p.Elem()

	if v.CanSet() {
		v.SetFloat(7.1)
	}
	fmt.Println(x)
}"},{"order":9,"type":"subheading","text":"Inspecting Struct Fields and Tags"},{"order":10,"type":"paragraph","text":"Reflection is heavily used to inspect struct types, iterate over their fields, and read metadata stored in struct tags. This is the foundation of mapping data from databases or JSON documents."},{"order":11,"type":"code","text":"package main

import (
	"fmt"
	"reflect"
)

type User struct {
	Name  string `json:"name" validate:"required"`
	Age   int    `json:"age"`
}

func main() {
	u := User{Name: "Alice", Age: 30}
	t := reflect.TypeOf(u)
	v := reflect.ValueOf(u)

	for i := 0; i < t.NumField(); i++ {
		field := t.Field(i)
		value := v.Field(i)
		jsonTag := field.Tag.Get("json")
		fmt.Printf("Field: %s, Type: %s, Value: %v, JSON Tag: %s\n", field.Name, field.Type, value, jsonTag)
	}
}"},{"order":12,"type":"bullet_point","text":"Use 'reflect.TypeOf()' to obtain the type metadata."},{"order":13,"type":"bullet_point","text":"Use 'reflect.ValueOf()' to inspect or manipulate the underlying data."},{"order":14,"type":"bullet_point","text":"Always pass pointers to reflection functions if you intend to mutate the original variables using 'Elem()'."},{"order":15,"type":"bullet_point","text":"Be cautious: reflection incurs a runtime performance penalty and bypasses compile-time safety checks, so use it sparingly."}]
